function definition = f90_xmech06_definition
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
official = jsondecode(fileread(simuverity_official_scenarios_path()));
runtimeRoot = string(getenv("SIMUVERITY_RUNTIME_SUBMISSION_BUNDLE"));
referencePresence = lower(strtrim(string("present")));
assert(strlength(referencePresence) > 0, "SimuVerity:F90:XMECH06:ReferenceBinding", ...
    "The evaluator reference file presence binding is missing.");
definition = struct( ...
    "task_id", "F90-XMECH-06", ...
    "public_spec", fullfile(taskRoot, "public_spec.json"), ...
    "official_scenarios", simuverity_official_scenarios_path(), ...
    "reference_model", fullfile(runtimeRoot, "sm_car.slx"), ...
    "reference_file_presence", referencePresence, ...
    "scenarios", official.scenarios, ...
    "evidence_entry", "f90_xmech06_extract_evidence_core", ...
    "offline_scorer", fullfile(fileparts(mfilename("fullpath")), ...
        "f90_xmech06_offline_scorer.py"), ...
    "admission_threshold_raw", 85.0);
end
